// One authored beginner route supplies classroom steps and the complete reading view.
// Demonstrations and checks are teacher-written. Past-paper coverage is deliberately narrow.
const ids = (requirement, ...numbers) => numbers.map(number => `S1.${String(requirement).padStart(2, '0')}.A${String(number).padStart(2, '0')}`);
const table = (headers, rows) => ({ headers, rows });
const step = (title, body, extra = {}) => ({ title, body, ...extra });
const worked = (title, setup, steps, conclusion) => ({ title, setup, steps, conclusion });
const stimulus = (title, items, grid) => ({ title, items, ...(grid ? { table: grid } : {}) });
const figure = (name, alt, caption) => ({ asset: `/assets/course-v3/section-1/${name}.svg`, alt, caption });

