        check: { prompt: 'Convert eight-bit one’s complement 11111010 to eight-bit two’s complement without changing its value.', answer: 'Decode one’s complement first: invert to 00000101, so the value is −5. Two’s complement −5 is obtained by inverting 00000101 and adding one, giving 11111011. The value stays −5 although the stored pattern changes.' },
        papers: [], takeaway: 'Conversion preserves a value under a new rule. Reinterpretation gives unchanged bits a possibly different value.',
        trap: 'A correct calculation performed under the wrong representation gives the wrong answer to the task.',
